__NUXT_JSONP__("/ar/how-to-apply/short", (function(a){return {data:[{details:{slug:"ar",pageTitle:"خطوت التقديم لطلبة المدة القصيرة | Mentor Language Institute",pageDescription:a,title:"خطوت التقديم لطلبة المدة القصيرة",image:"\u002Fimages\u002Fshort\u002Fpassport-jp.jpg",category:[{title:"أقل من 90 يوما",content:[a,"- شخص يعيش خارج الولايات المتحدة.\u003Cbr \u002F\u003E-A شخص يخطط للبقاء في الولايات المتحدة أقل من 90 يوما."]},{title:"خطوات التقديم",image:"\u002Fimages\u002Fshort\u002Fmli-design-apply-short-en.jpg",ordered_content:[" تقديم في معهد منتور","تقديم الوثائق","تلقي التأكيد النهائي","مغادرة الولايات المتحدة."],content:["ولا يحتاج الطلاب الدوليون لفترات قصيرة إلى الحصول على تأشيرة لدخول الولايات المتحدة. ومع ذلك فمن المستحسن أن إكمال عملية التقديم و التسجيل في أقرب وقت ممكن لتأمين السكن ومكانك في المعهد.","معهد منتور بشكل خاص يكون مزدحم جدا خلال العطلات الصيفية وفترات الربيع. لذلك، حتى بالنسبة للدراسة على المدى القصير، فإننا نوصي بإكمال التقديم  قبل شهرين على الأقل من مغادرة بلادك."],types:[{title:"سياسة الإلغاء",content:["سيتم احتساب رسوم التسجيل البالغة 150 دولارا في وقت تقديم الطلب. رسوم التسجيل غير قابلة للاسترداد بغض النظر عن رفض الطلب أو إلغاء التسجيل. وتشمل الاستثناءات السكن غير الكافي."]}]},{title:"حول الخطوات بعد التقديم",image:"\u002Fimages\u002Fshort\u002Fmli-short-en.jpg",content:["بعد تطبيق الطلاب، يقوم نظام iMLI بمعالجة الخطوت. يمكن للطلاب متابعة و تتبع العملية التي يتم سردها على iMLI."],types:[{title:"تقديم عبر الإنترنت",content:["املأ المعلومات عن حالة التأشيرة \u003Cbr \u002F\u003E الاتصال بنا عبر iMLI لجميع الاستفسارات","تقديم في الاسفل."]}]}],btn_label:"نموذج الطلب عبر الإنترنت",admission:{link:"\u002Far\u002Fadmission",content:["* يرجى توفير بطاقة الائتمان الخاصة بك."]},dir:"\u002Fshort",path:"\u002Fshort\u002Far",extension:".json",createdAt:"2026-10-22T16:31:31.055Z",updatedAt:"2025-05-26T12:06:27.916Z"}}],fetch:{},mutations:void 0}}("من هو المؤهل لتقديم طلب للحصول على دراسة لمدة قصيرة؟")));